create table public.interests (id uuid primary key default extensions.gen_random_uuid(), sender_id uuid not null references public.profiles(id) on delete cascade, recipient_id uuid not null references public.profiles(id) on delete cascade, status public.interest_status not null default 'pending', message text check (char_length(message) <= 500), responded_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(sender_id <> recipient_id), unique(sender_id, recipient_id));
create table public.matches (id uuid primary key default extensions.gen_random_uuid(), user_low_id uuid not null references public.profiles(id) on delete cascade, user_high_id uuid not null references public.profiles(id) on delete cascade, status public.match_status not null default 'active', matched_at timestamptz not null default now(), unmatched_at timestamptz, check (user_low_id < user_high_id), unique(user_low_id, user_high_id));
create table public.conversations (id uuid primary key default extensions.gen_random_uuid(), match_id uuid not null unique references public.matches(id) on delete cascade, last_message_at timestamptz, created_at timestamptz not null default now());
create table public.messages (id uuid primary key default extensions.gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid not null references public.profiles(id) on delete restrict, kind public.message_kind not null default 'text', body text check (char_length(body) between 1 and 4000), media_path text, client_message_id uuid not null, read_at timestamptz, deleted_at timestamptz, created_at timestamptz not null default now(), check ((kind = 'text' and body is not null) or (kind <> 'text' and media_path is not null)), unique(sender_id, client_message_id));
create table public.blocked_users (blocker_id uuid not null references public.profiles(id) on delete cascade, blocked_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(blocker_id, blocked_id), check(blocker_id <> blocked_id));
create table public.reports (id uuid primary key default extensions.gen_random_uuid(), reporter_id uuid not null references public.profiles(id) on delete restrict, reported_id uuid not null references public.profiles(id) on delete restrict, reason text not null check (char_length(reason) between 5 and 1000), status public.report_status not null default 'open', reviewer_id uuid references public.profiles(id) on delete set null, resolution_notes text, created_at timestamptz not null default now(), resolved_at timestamptz, check(reporter_id <> reported_id));
create table public.subscription_plans (id uuid primary key default extensions.gen_random_uuid(), code text not null unique, name text not null, price_minor integer not null check(price_minor >= 0), currency char(3) not null default 'INR', interval_months smallint not null check(interval_months between 1 and 24), features jsonb not null default '{}'::jsonb, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.user_subscriptions (id uuid primary key default extensions.gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete restrict, plan_id uuid not null references public.subscription_plans(id) on delete restrict, provider text not null, provider_subscription_id text unique, status public.subscription_status not null, current_period_start timestamptz not null, current_period_end timestamptz not null, cancel_at_period_end boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(current_period_end > current_period_start));
create table public.notifications (id uuid primary key default extensions.gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, type public.notification_type not null, title text not null, body text, data jsonb not null default '{}'::jsonb, read_at timestamptz, created_at timestamptz not null default now());
create table public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references public.profiles(id) on delete set null, action text not null, entity_type text not null, entity_id uuid, ip inet, user_agent text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.rate_limit_events (id bigint generated always as identity primary key, subject text not null, action text not null, occurred_at timestamptz not null default now());
create index interests_recipient_status_idx on public.interests(recipient_id, status, created_at desc);
create index messages_conversation_cursor_idx on public.messages(conversation_id, created_at desc, id desc) where deleted_at is null;
create index notifications_inbox_idx on public.notifications(profile_id, created_at desc) where read_at is null;
create index audit_logs_entity_idx on public.audit_logs(entity_type, entity_id, created_at desc);
create index rate_limit_events_idx on public.rate_limit_events(subject, action, occurred_at desc);
create trigger interests_updated_at before update on public.interests for each row execute function public.set_updated_at();
create trigger subscriptions_updated_at before update on public.user_subscriptions for each row execute function public.set_updated_at();
